from pathlib import Path
import train as tr
def main():
 p=argparse.ArgumentParser();p.add_argument("--local",type=Path,default=Path(__file__).resolve().parent);p.add_argument("--large",type=Path,required=True);p.add_argument("--evaluation",type=Path,required=True);p.add_argument("--diagnostics",type=Path,required=True);p.add_argument("--report",type=Path,required=True);p.add_argument("--supplement",type=Path,required=True);p.add_argument("--cost-v2",type=Path,required=True);p.add_argument("--cost-m2",type=Path,required=True);p.add_argument("--cost-end-to-end-v2",type=Path,required=True);p.add_argument("--cost-end-to-end-m2",type=Path,required=True);a=p.parse_args()
 required={"formal":a.local/"FORMAL_STATUS.json","training_audit":a.local/"TRAINING_AUDIT.json","prediction":a.local/"PREDICTION_STATUS.json","evaluation":a.evaluation/"SUMMARY.json","evaluation_audit":a.local/"EVALUATION_AUDIT.json","diagnostics":a.diagnostics/"SUMMARY.json","supplement":a.supplement/"SUMMARY.json","report":a.report/"REPORT_SUMMARY.json","cost_v2":a.cost_v2,"cost_m2":a.cost_m2,"cost_end_to_end_v2":a.cost_end_to_end_v2,"cost_end_to_end_m2":a.cost_end_to_end_m2}
 values={k:json.loads(v.read_text()) for k,v in required.items()};checks={"formal_24":values["formal"].get("status_counts")=={"complete":24},"training_audit":values["training_audit"].get("status")=="pass","prediction_24":values["prediction"].get("complete")==24 and values["prediction"].get("status")=="complete","evaluation_complete":values["evaluation"].get("status")=="complete","evaluation_audit":values["evaluation_audit"].get("status")=="pass","diagnostics_6":values["diagnostics"].get("status")=="complete" and values["diagnostics"].get("cases")==6,"supplement_complete":values["supplement"].get("status")=="complete" and values["supplement"].get("audit",{}).get("trial_metric_replay") is True and values["supplement"].get("audit",{}).get("matched_constraints") is True,"report_complete":values["report"].get("status")=="complete","costs_complete":all(values[k].get("status")=="complete" for k in ("cost_v2","cost_m2","cost_end_to_end_v2","cost_end_to_end_m2")),"streaming_direct_parity":all(values[k].get("streaming_direct_score_max_abs",1)>-1 and values[k].get("streaming_direct_score_max_abs",1)<=1e-5 for k in ("cost_end_to_end_v2","cost_end_to_end_m2")),"test_not_consumed":all(v.get("test_consumed",False) is False for v in values.values())}
 if not all(checks.values()):raise ValueError(checks)
