 local_index={x:tr.sha(a.local/x) for x in sources};result_index={k:{"path":str(v),"sha256":tr.sha(v)} for k,v in required.items()};logs_index={str(x.relative_to(a.local)):tr.sha(x) for x in sorted((a.local/"logs").glob("*.log")) if x.name!="post_finalize.log"};tr.atomic_json(a.local/"ARTIFACT_INDEX.json",{"schema":"round19_artifact_index_v1","local":local_index,"results":result_index,"logs":logs_index,"checkpoint_index_sha256":tr.sha(a.local/"CHECKPOINT_INDEX.json"),"test_consumed":False})
