 tr.atomic_json(a.local/"REVIEW_READY.json",ready)
 lines=["# Round 19 independent review handoff","",f"Status: `{ready['status']}`. Root acceptance is intentionally pending independent review.","","Review the locked scientific protocol and engineering revision, all 24 checkpoint identities and training audit, unified corrected-pAUC evaluation with four preregistered contrasts, FiLM/force/threshold-transfer diagnostics, actual two-suffix deployment costs, failure cases, and claim boundaries. `Q3_READINESS.md` records separate future-force prerequisites without using R19 validation for selection. `results/supplement/` contains reviewer-requested validation-only exact-score matching and fit-cutoff force-error trial performance; these do not alter locked evaluation or deployable thresholds.","",f"Critical indexes: `ARTIFACT_INDEX.json` ({ready['artifact_index_sha256']}) and `CHECKPOINT_INDEX.json` ({ready['checkpoint_index_sha256']}).","","No test role, Q2/Q3, external-domain adaptation, force adaptation, C2, or out-of-scope training was consumed."]
 (a.local/"HANDOFF.md").write_text("\n".join(lines)+"\n");print(json.dumps(ready,indent=2))
